namespace WypozyczalniaSportowa.Data; public sealed class AuditLogWriter : IDisposable { private readonly StreamWriter _writer; public AuditLogWriter(string path) { Directory.CreateDirectory(Path.GetDirectoryName(path)!); _writer = new StreamWriter(new FileStream(path, FileMode.Append, FileAccess.Write, FileShare.Read)) { AutoFlush = true }; } public void Write(string message) => _writer.WriteLine($"{DateTime.Now:yyyy-MM-dd HH:mm:ss} | {message}"); public void Dispose() { _writer.Dispose(); GC.SuppressFinalize(this); } public override string ToString() => "Dziennik zdarzeń wypożyczalni"; }
